/** List all users */
export function useListUsers(query?: { search?: string; country?: string; role?: 'Admin' | 'Manager' | 'Employee' | 'Guest'; isActive?: boolean; limit?: number /* default: 25 */ }, options?: Omit<UseQueryOptions<Users, ApiError>, 'queryKey' | 'queryFn'>) {
  const api = useApiService();
  return useQuery({
    queryKey: usersKeys.list(query),
    queryFn: async () => {
      const result = await api.users.listUsers(query);
      if (result.status === 'ok') {
        return result.data;
      }
      throw new ApiError(
        result.response.status,
        result.response.statusText,
        'error' in result ? result.error.message : 'Request failed',
        result.response,
      );
    },
    ...options,
  });
}

